"""Generate current service reports from published data and the dated research ledger."""
from collections import Counter
from service_catalog import ROOT,DIRECTORY,read,write,merged_catalog
from administrative_coverage import state_key

def table(headers,rows):return '\n'.join(['| '+' | '.join(headers)+' |','| '+' | '.join(['---']*len(headers))+' |']+['| '+' | '.join(str(v).replace('|','/') for v in row)+' |' for row in rows])+'\n'
def document(name,text):(ROOT/'docs'/name).write_text(text,encoding='utf-8')
def main():
    c=merged_catalog();services=c['services'];ledger=read(DIRECTORY/'phase3c-ledger.json');new=ledger['candidates'];queue=read(DIRECTORY/'review_queue.json')
    pending=[q for q in queue if q['status'] in ('NEEDS_REVIEW','REVISION_NEEDS_REVIEW')]
    aliases={'nct of delhi':'delhi','andaman and nicobar islands':'andaman and nicobar islands','dadra and nagar haveli and daman and diu':'dadra and nagar haveli and daman and diu'}
    def key(s):return aliases.get(state_key(s),state_key(s))
    admin=read(ROOT/'data/collection/phase2b-2026-10-15/administrative_units.json')['stateUnits']
    assert len(admin)==36
    def matching(rows,state):return [r for r in rows if key(r.get('state') or '')==key(state)]
    coverage=[]
    for unit in admin:
        name=unit['name'];investigated=matching(new,name);published=matching(services,name)
        coverage.append(dict(state=name,type=unit['type'],investigated=len(investigated),discovered=sum(r['discovered'] for r in investigated),sourceReviewed=sum(r['sourceReviewed'] for r in investigated),published=len(published),lastReviewed=max((s['verifiedOn'] for s in published),default=None)))
    central=[r for r in new if r['level']=='Central'];levels=Counter(s['level'] for s in services);modes=Counter(s['applicationMode'] for s in services)
    cats=Counter(cat for s in services for cat in s['categories']);groups=Counter(f['text'] for s in services for f in s.get('beneficiaryGroups') or [])
    original_cases={a['id'] for a in ledger['existingCaseReviews']}
    used_organizations=len({s['organizationId'] for s in services})
    summary=dict(version=c['version'],websites=len(c['websites']),services=len(services),organizations=len(c['serviceOrganizations']),newInvestigated=len(new),newDiscovered=sum(r['discovered'] for r in new),newSourceReviewed=sum(r['sourceReviewed'] for r in new),newPublished=sum(r['decision']=='publish' for r in new),pendingServices=len(pending),existingCasesRechecked=len(original_cases),existingCasesStillPending=sum(q['id'] in original_cases for q in pending),pendingWebsites=len(read(ROOT/'data/review_queue.json')['records']),
        publishedOrganizations=used_organizations,unknownEligibility=sum(s.get('eligibility') is None for s in services),unknownDocuments=sum(s.get('documents') is None for s in services),unknownGroups=sum(s.get('beneficiaryGroups') is None for s in services),levels=dict(levels),modes=dict(modes),categories=dict(cats),documentedGroups=dict(groups),states=coverage)
    write(ROOT/'data/validation_reports/phase3c-service-coverage.json',summary)
    matrix='# Service coverage matrix — Phase 3C\n\nSnapshot: 16 October 2026, service catalog v13. Reproduce with `python tools/report_service_coverage.py`. Counts come from `data/services/catalog.json` and `phase3c-ledger.json`; all 36 administrative rows use the retained [LGD public state table](https://lgdirectory.gov.in/globalviewstateforcitizen.do), not portal counts.\n\n'
    matrix+='## How to read the counts\n\nEach additional candidate has a stable ID. Investigated = targeted source inspected; discovered = a distinct operation named in a readable current source; source-reviewed = the selected facts and route decision completed the publication review; published = an admitted service, never a general website. New columns cover this phase only; published totals include the 25 preserved baseline services. A held candidate may have partially reviewed evidence without a completed publication review. Source review does not mean a completed government transaction.\n\n'
    matrix+=table(['Scope','New investigated','New discovered','New source-reviewed','Published total'],[['Central',len(central),sum(r['discovered'] for r in central),sum(r['sourceReviewed'] for r in central),levels['Central']],['All regional scopes',len(new)-len(central),sum(r['discovered'] for r in new if r['level']!='Central'),sum(r['sourceReviewed'] for r in new if r['level']!='Central'),len(services)-levels['Central']],['District',sum(r['level']=='District' for r in new),sum(r['level']=='District' and r['discovered'] for r in new),0,levels['District']],['Local',sum(r['level']=='Local' for r in new),sum(r['level']=='Local' and r['discovered'] for r in new),0,levels['Local']]])
    matrix+='\n## States and union territories\n\nLocal candidates are counted under their parent state; this does not establish statewide service availability. UT service records use the backward-compatible `State` level plus canonical state/UT name; the administrative type below retains the UT distinction.\n\n'
    matrix+=table(['State / UT','Type','New investigated','Discovered','Source-reviewed','Published total','Last published review'],[[r['state'],r['type'],r['investigated'],r['discovered'],r['sourceReviewed'],r['published'],r['lastReviewed'] or 'None'] for r in coverage])
    matrix+='\n## Categories, modes and verification\n\nCategory totals count membership and can exceed the number of services. Zero means no published service in this dataset.\n\n'+table(['Category','Published services'],[[cat['title'],cats[cat['id']]] for cat in c['categories']])
    matrix+='\n'+table(['Mode','Published'],[[mode,modes[mode]] for mode in ('online','assisted','information')])
    matrix+='\n'+table(['Verification status / date','Published'],[[str(k),v] for k,v in sorted(Counter((s['verificationStatus'],s['verifiedOn']) for s in services).items())])
    matrix+='\n## Documented applicant groups\n\nOnly sourced `beneficiaryGroups` facts count. Legacy title/eligibility text is not used to guess a group. These are overlapping service counts, not people or confirmed personal eligibility.\n\n'+table(['Documented group','Services'],sorted(groups.items()))
    matrix+=f'\nGroup metadata remains unknown for {summary["unknownGroups"]} services. Eligibility is unknown for {summary["unknownEligibility"]}; document lists are unknown for {summary["unknownDocuments"]}. Populated lists can be partial.\n\n## Research trail and decisions\n\n'
    matrix+=table(['Candidate','Jurisdiction','Decision','Official source'],[[r['id'],r.get('state') or 'Central',r['decision'],f'[Source]({r["sources"][0]["url"]})'] for r in new])
    matrix+='\nNo nationwide coverage or active application window is implied. District/local records are not published yet. Directory reuse permission and production release checks remain separate from local development.\n'
    document('SERVICE_COVERAGE_MATRIX.md',matrix)
    gaps='# Service gaps and evidence audit — Phase 3C\n\nSnapshot: 16 October 2026. Generated by `tools/report_service_coverage.py`. See the [coverage matrix](SERVICE_COVERAGE_MATRIX.md) for exact jurisdiction/category denominators and official sources.\n\n'
    gaps+=f'## Actual scope\n\nThe catalog has {len(services)} services and 7,347 unchanged websites. Of 54 additional investigations, 27 were published and 27 remain pending. Four older cases were rechecked and remain pending: 31 unresolved service cases in total. All 3,823 website-review cases are untouched. Five states/UTs have published regional services; Himachal has investigated candidates only. No district or local service is published. General portals are excluded from service-coverage counts.\n\n'
    gaps+='## Existing four cases\n\n'+table(['Operation','Dated decision / remaining gap','Evidence'],[[a['id'],a['reason'],'; '.join(f'[Official source]({e["url"]})' for e in a['reviewEvidence'])] for a in ledger['existingCaseReviews']])
    gaps+='\n## Weak, ambiguous or incomplete facts\n\n'
    gaps+='- DigiLocker FAQ bodies remain JavaScript shells in this retrieval; homepage feature names cannot establish an issued-document or consent workflow.\n- Driving-licence material mixes learner/permanent and older conditions; current state-specific Sarathi entry remains unconfirmed. A failed request is not evidence of retirement.\n- PMEGP has one explicitly reviewed revision: normal TLS works on the canonical non-www host, while the www host fails validation. Its current public notice says fresh intake is unavailable; there is no Apply action. Original nullable facts and service ID remain.\n- Kerala Caste means OBC while Community means SC/ST in its FAQ. Ration-card DB verification instructions differ from the supporting-documents table; no universal upload requirement is inferred.\n- Odisha modals contain useful source facts but some eligibility language appears old/incomplete. Full eligibility stays null, fee statements are limited to government charges, time standards are not delivery guarantees, and unreadable directApply entries remain information-only.\n- Puducherry procedure PDFs have apparently mismatched document appendices and the eDistrict TLS connection failed; document/eligibility fields remain null, with no Apply action.\n- Overseas voter Form 6A has older qualifying-date examples/legacy links; it remains pending. The current e-PAN manual includes consent-based DigiLocker DOB evidence, so older no-documents descriptions are not used.\n- Legacy AICTE evidence includes older guidelines linked from current NSP; academic-year applicability must be reconfirmed. Historical review dates are not source publication dates or live availability.\n\n'
    gaps+=f'Unknown eligibility: {summary["unknownEligibility"]}/{len(services)}; unknown documents: {summary["unknownDocuments"]}/{len(services)}; unknown group metadata: {summary["unknownGroups"]}/{len(services)}. These are explicit gaps, not claims of unrestricted eligibility or no required documents.\n\n'
    gaps+='## Identity, ownership and duplicate limits\n\nAll service IDs, website IDs and exact operator relationships validate. All 25 old service IDs remain; 24 records are byte-equivalent JSON objects and PMEGP alone has a retained, digest-reviewed revision. Old publication decisions remain in the queue. The operator registry records exact existing website operators; responsible authority is separate department text, without invented department IDs or independent ownership certification.\n\nExact normalized title + department + level + state + district duplicates are rejected before publication. Shared login URLs are not duplicates. Explicit possibleDuplicateOf/duplicateOf ambiguity flags block publication. This detects strong matches, not all semantic aliases: similarly named certificates across states require human source review. No additional duplicate record was published in this batch.\n\n'
    gaps+='## Search and next editorial priorities\n\nNew regional certificate, e-PAN and voter intents have concrete service records. National generic certificate searches can still rank several states; users should select their state. Bihar pension, most other state services, district/local transactions, broader employment, education and grievance services remain gaps. First complete pending per-service checklists and current routes, then diversify categories using authoritative sources. Do not turn a portal match into an invented service. Current query/performance evidence is in [search QA](SEARCH_QA_REPORT.md).\n\n'
    gaps+=table(['Remaining new candidate','Reason'],[[r['id'],r['reason']] for r in new if r['decision']=='pending'])
    gaps+='\nLocal source inspection, signed packages and APK testing do not establish public-distribution permission. NIC directory reuse and site-specific terms require release review before publication; no public release occurred.\n'
    document('SERVICE_GAPS_REPORT.md',gaps)
    report='# Service catalog report — Phase 3C\n\nCurrent snapshot: 16 October 2026; app 0.4.1/code 5; service/runtime catalog v13. Reproduce with `python tools/report_service_coverage.py`.\n\n'
    report+=table(['Measure','Actual'],[['Published services',len(services)],['New investigations / discovered',f'{len(new)} / {sum(r["discovered"] for r in new)}'],['New published / held','27 / 27'],['Older pending cases rechecked / still pending','4 / 4'],['Explicit old-service revisions','1 (PMEGP)'],['All pending service cases',len(pending)],['Website operator registry / referenced by published services',f'{len(c["serviceOrganizations"])} / {used_organizations} (one pending-only Himachal operator)'],['Unchanged websites / pending website cases','7,347 / 3,823'],['Unknown eligibility / documents',f'{summary["unknownEligibility"]} / {summary["unknownDocuments"]}']])
    report+='\nSee [coverage](SERVICE_COVERAGE_MATRIX.md), [evidence gaps](SERVICE_GAPS_REPORT.md), [search QA](SEARCH_QA_REPORT.md) and [build/test QA](QA_REPORT.md) for scope and results. Verified means reviewed official information, not a completed transaction, confirmed personal eligibility or a current application window.\n\n## Reproduce the editorial snapshot\n\n```powershell\npython tools/prepare_phase3c.py\npython tools/service_catalog.py amend-pending data/services/phase3c-pending-reviews.json\npython tools/service_catalog.py import data/services/phase3c-candidates.json --revision\npython tools/service_catalog.py publish data/services/phase3c-approvals.json\npython tools/service_catalog.py check\npython tools/report_service_coverage.py\npython tools/package_extension.py\npython tools/package_catalog.py update --version 14 --output artifacts/catalog-v14.jansetu\n```\n\nThese replay retained dated research and decisions; they do not refresh a source. Replay preserves published decisions and is idempotent. For a new review date, retrieve explicit official URLs with normal TLS into a new dated research batch, inspect their actual content/redirects, stage new or revised drafts and approve exact candidate digests with named reviewer/notes. Unresolved stubs use a digest-bound amendment preserving their previous decision/history. New services require explicit route evidence; null application URLs remain information-only. Whole-collection validation runs before either publication file is replaced; writes are individually atomic, not a cross-file database transaction. Back up editorial files before a new batch.\n\n## Published service index\n\n'
    report+=table(['Service ID','Jurisdiction','Mode','Department','Official information'],[[s['id'],s.get('state') or 'Central',s['applicationMode'],s['department'],f'[Source]({s["informationUrl"]})'] for s in services])
    report+='\nThe Android build merges the service catalog with the protected website directory and generates compact runtime assets. The Chrome companion receives the same merged data; its interface still lists portals/guides, without a new service/tracker UI. The limited readability profile is unchanged and cannot speed up government servers. My Applications remains encrypted, local and user-maintained; catalog updates do not write its database. No government login, OTP, cloud sync or live-status API was introduced.\n\nThe v14 signed file is a local update demonstration of the v13 content. Private signing material is excluded. Local development readiness is separate from distribution permission and release approval.\n'
    document('SERVICE_CATALOG_REPORT.md',report)
    benchmark=read(ROOT/'data/validation_reports/phase3c-search.json')
    if benchmark and benchmark['services']==len(services):
        search='# Search QA report — Phase 3C\n\nActual JDK 17 run on the full generated runtime asset: 7,347 websites and 52 services. `SearchPerformanceTest` uses 14 queries, one warm-up pass and five measured repetitions (70 timed queries). Raw results: `data/validation_reports/phase3c-search.json`. Reproduce with `JANSETU_SEARCH_BENCHMARK` set to that absolute path, then run `:app:testDebugUnitTest --rerun-tasks` and this report generator.\n\n'
        search+=table(['Measurement','Observed'],[['Index preparation (ms)',f'{benchmark["indexMs"]:.2f}'],['Median query (ms)',f'{benchmark["medianQueryMs"]:.2f}'],['P95 query (ms)',f'{benchmark["p95QueryMs"]:.2f}']])
        search+='\nThese are observed JVM measurements, not Android UI frame/startup or production latency guarantees. The Phase 3A eight-query run with 25 services measured median/P95 34.22/66.19 ms; the expanded query mix and machine load differ, so this is not a controlled before/after performance comparison. Phase 3A raw before/after JSON remains retained. Search/index architecture is unchanged.\n\n'
        search+=table(['Query','Actual top three'],[[q['query'],'; '.join(f'{r["type"]}: `{r["id"]}`' for r in q['topResults'][:3])] for q in benchmark['queries']])
        search+='\n## Correctness and limits\n\nJVM regressions verify top service IDs for Kerala income, Delhi OBC, Odisha resident and Puducherry residence queries with explicit state/type filters; e-PAN/new-voter intents; exact DigiLocker portal preference; category/type/central filters; no Bihar pension or Himachal/local service coverage. Existing scholarship/jobs/pension/birth-print/subsidy/complaint intents remain tested. No search result decides eligibility or a current intake window.\n\nGeneric national certificate/pension queries can rank records from different states. A state filter restricts service jurisdiction; it does not convert a portal into a service. Kerala Caste/OBC and Community/SC-ST naming remain distinct. Source-reviewed information-only services remain searchable but have no Apply or service-tracker shortcut. Confirmed Delhi/Kerala actions open the reviewed shared official login entry; authentication and submission are not claimed. Android service UI tests exercise the exact URL callbacks and unknown/no-Apply presentation; complete outcomes are in [QA](QA_REPORT.md).\n'
        document('SEARCH_QA_REPORT.md',search)
    print({k:v for k,v in summary.items() if k not in ('states','categories','documentedGroups')})

if __name__=='__main__':main()
